CoreGasVentPinMaker.ironStock=18; CoreGasVentPinMaker.bronzeStock=14; CoreGasVentPinMaker.woodStock=10; CoreGasVentPinMaker.leatherStock=8; CoreGasVentPinMaker.silverStock=8; CoreGasVentPinMaker.goldStock=6; CoreGasVentPinMaker.jewelStock=4; CoreGasVentPinMaker.pearlStock=4
CoreGasVentPinMaker.productStock = {}; CoreGasVentPinMaker.buildings = {}; CoreGasVentPinMaker.maker = nil; CoreGasVentPinMaker.activeMaking = {}; CoreGasVentPinMaker.totalProducts = 0; CoreGasVentPinMaker.dayTimer = 0
function CoreGasVentPinMaker.init() CoreGasVentPinMaker.ironStock=18; CoreGasVentPinMaker.bronzeStock=14; CoreGasVentPinMaker.woodStock=10; CoreGasVentPinMaker.leatherStock=8; CoreGasVentPinMaker.silverStock=8; CoreGasVentPinMaker.goldStock=6; CoreGasVentPinMaker.jewelStock=4; CoreGasVentPinMaker.pearlStock=4; CoreGasVentPinMaker.productStock={}; CoreGasVentPinMaker.buildings={}; CoreGasVentPinMaker.maker=nil; CoreGasVentPinMaker.activeMaking={}; CoreGasVentPinMaker.totalProducts=0; CoreGasVentPinMaker.dayTimer=0; print("[CoreGasVentPinMaker] Royal Core Gas Vent Pin Maker System initialized (6 products, 4 buildings)") end
function CoreGasVentPinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoreGasVentPinMaker.maker={name=n or ("Boltnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Boltnik najet: %s (spretnost: %d)",CoreGasVentPinMaker.maker.name,s),"success") end; return true end
function CoreGasVentPinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoreGasVentPinMaker.build(id) local ok,e=CoreGasVentPinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoreGasVentPinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoreGasVentPinMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoreGasVentPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoreGasVentPinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoreGasVentPinMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoreGasVentPinMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoreGasVentPinMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoreGasVentPinMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoreGasVentPinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoreGasVentPinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoreGasVentPinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoreGasVentPinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoreGasVentPinMaker.buildings==0 then return false,"Potrebna boltna delavnica" end; if not CoreGasVentPinMaker.maker then return false,"Potreben boltnik" end; return true end
function CoreGasVentPinMaker.make(pt,qty) qty=qty or 1; local ok,e=CoreGasVentPinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoreGasVentPinMaker.ironStock=CoreGasVentPinMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoreGasVentPinMaker.bronzeStock=CoreGasVentPinMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoreGasVentPinMaker.woodStock=CoreGasVentPinMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoreGasVentPinMaker.leatherStock=CoreGasVentPinMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoreGasVentPinMaker.silverStock=CoreGasVentPinMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoreGasVentPinMaker.goldStock=CoreGasVentPinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoreGasVentPinMaker.jewelStock=CoreGasVentPinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoreGasVentPinMaker.pearlStock=CoreGasVentPinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoreGasVentPinMaker.maker then t=math.max(1,t-math.floor(CoreGasVentPinMaker.maker.skill/13)) end; table.insert(CoreGasVentPinMaker.activeMaking,{id="coregasventpin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoreGasVentPinMaker.completeMaking(m) local q=1.0+(CoreGasVentPinMaker.getQualityBonus()/100); if CoreGasVentPinMaker.maker then q=q+(CoreGasVentPinMaker.maker.skill/140) end; q=math.min(2.5,q); CoreGasVentPinMaker.productStock[m.productType]=(CoreGasVentPinMaker.productStock[m.productType] or 0)+m.quantity; CoreGasVentPinMaker.totalProducts=CoreGasVentPinMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoreGasVentPinMaker.maker then CoreGasVentPinMaker.maker.itemsMade=CoreGasVentPinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoreGasVentPinMaker.maker.skill=math.min(100,CoreGasVentPinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bolt izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coregasventpin.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoreGasVentPinMaker.update(dt) if not _G.state then return end; CoreGasVentPinMaker.dayTimer=CoreGasVentPinMaker.dayTimer+dt; if CoreGasVentPinMaker.dayTimer>=30 then CoreGasVentPinMaker.dayTimer=0; for i=#CoreGasVentPinMaker.activeMaking,1,-1 do local m=CoreGasVentPinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoreGasVentPinMaker.completeMaking(m); table.remove(CoreGasVentPinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoreGasVentPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoreGasVentPinMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoreGasVentPinMaker.getStats() return {ironStock=CoreGasVentPinMaker.ironStock,bronzeStock=CoreGasVentPinMaker.bronzeStock,woodStock=CoreGasVentPinMaker.woodStock,leatherStock=CoreGasVentPinMaker.leatherStock,silverStock=CoreGasVentPinMaker.silverStock,goldStock=CoreGasVentPinMaker.goldStock,jewelStock=CoreGasVentPinMaker.jewelStock,pearlStock=CoreGasVentPinMaker.pearlStock,productStock=CoreGasVentPinMaker.productStock,numBuildings=#CoreGasVentPinMaker.buildings,hasMaker=CoreGasVentPinMaker.maker~=nil,makerName=CoreGasVentPinMaker.maker and CoreGasVentPinMaker.maker.name or "—",makerSkill=CoreGasVentPinMaker.maker and CoreGasVentPinMaker.maker.skill or 0,activeMaking=#CoreGasVentPinMaker.activeMaking,totalProducts=CoreGasVentPinMaker.totalProducts} end
return CoreGasVentPinMaker
